using HakutaiKagami.Core.Contracts;
using HakutaiKagami.Core.Messaging;
using Xunit;
namespace HakutaiKagami.Tests;
public sealed class UnitDirectiveCancellationTests
{
 static void At(WorldSession s,long at)=>NewGameWorldTests.At(s,at);
 static NewMilitaryInput Input(WorldSession s,NewMilitaryAction action)=>new(new("request:unit-recipient/"+s.Revision+"/"+action),action);
 static void Send(WorldSession s,NewMilitaryAction action,long amount=0){var result=s.DecideNewMilitary(Input(s,action) with{Amount=amount},s.PlayerControl,s.Revision);Assert.True(result.Code==ResultCode.Accepted,result.VisibleReason);}
 static void Open(WorldSession s){foreach(var m in s.GetActorView(s.PlayerControl).Messages.Where(m=>m.KnownBody==null).ToArray())Assert.Equal(ResultCode.Accepted,s.Open(s.PlayerControl,m.Id,s.Revision).Code);}
 static WorldSession Away(){var s=NewGameWorldTests.Session([NewGameWorldTests.Officer(site:"site:kofu",role:StartTemplate.Retainer,lord:"person:shingen")]);Assert.Equal(ResultCode.Accepted,s.DecideNewMilitary(Input(s,NewMilitaryAction.Request) with{ObservationPolicy=NewGameMilitary.ObservationContract},s.PlayerControl,s.Revision).Code);At(s,2);Open(s);Send(s,NewMilitaryAction.Accept);At(s,4);Open(s);Send(s,NewMilitaryAction.Pickup);Send(s,NewMilitaryAction.Load,100000);Send(s,NewMilitaryAction.Deploy);var a=NewGameMilitary.Anchor(s.DiagnosticSnapshot());Assert.Equal(ResultCode.Accepted,s.DecideNewMilitary(Input(s,NewMilitaryAction.Form) with{A=new(a.X+90000,a.Y-10000),B=new(a.X+90000,a.Y+10000)},s.PlayerControl,s.Revision).Code);At(s,s.DiagnosticSnapshot().NewMilitary!.Orders.Last().Routes.SelectMany(r=>r).Max(l=>l.EndAt)+1);Send(s,NewMilitaryAction.Handoff);Send(s,NewMilitaryAction.Withdraw);At(s,s.DiagnosticSnapshot().NewMilitary!.Withdrawal!.Journeys.Last().Route.Max(l=>l.EndAt)+1);return s;}
 static NewMilitaryInput Query(WorldSession s,int unit)=>Input(s,NewMilitaryAction.InquireUnitKnown) with{InquiryTarget=new(NewGameMilitary.UnitRecipientContract,NewGameMilitary.SelectKnownTarget(s.DiagnosticSnapshot(),NewGameMilitary.UnitIds[unit])!),PostPolicy=NewGameMilitary.UnitReplyRecoveryContract,TransportPolicy=NewGameMilitary.UnitSenderEvidenceContract};
 static TroopDispatch Dispatch(WorldSession s,int unit){var i=Query(s,unit);var r=s.DecideNewMilitary(i,s.PlayerControl,s.Revision);Assert.True(r.Code==ResultCode.Accepted,r.VisibleReason);return s.DiagnosticSnapshot().NewMilitary!.UnitInquiry!.Dispatches.Last();}
 static UnitPostInquiryAnswer Answer(ContractWorld w,TroopReceipt receipt)=>ContractJson.Read<UnitPostInquiryAnswer>(System.Text.Encoding.UTF8.GetBytes(w.Messaging.Messages.Single(m=>m.Id==receipt.ReplyMessage).Body));

 static NewMilitaryInput Directive(WorldSession s,int unit,UnitDirectiveKind kind){var w=s.DiagnosticSnapshot();var k=NewGameMilitary.SelectKnownTarget(w,NewGameMilitary.UnitIds[unit])!;return Input(s,NewMilitaryAction.SendUnitDirective) with{Directive=new(NewGameMilitary.UnitDirectiveContract,k,kind,kind==UnitDirectiveKind.Move?new(k.Position.X+8000,k.Position.Y):null),DeliverBy=s.Seconds+600,PostPolicy=NewGameMilitary.UnitReplyRecoveryContract,TransportPolicy=NewGameMilitary.UnitSenderEvidenceContract,OriginalPolicy=NewGameMilitary.UnitDirectiveHoldingContract};}

 static TroopDispatch FailedOriginal(WorldSession s,bool learn=true,int index=1,UnitDirectiveKind kind=UnitDirectiveKind.Move,bool holding=true){Send(s,NewMilitaryAction.RemoteRecall);At(s,s.DiagnosticSnapshot().NewMilitary!.Withdrawal!.Dispatches.Last().DueAt+5);var i=Directive(s,index,kind) with{OriginalPolicy=holding?NewGameMilitary.UnitDirectiveHoldingContract:null};Assert.Equal(ResultCode.Accepted,s.DecideNewMilitary(i,s.PlayerControl,s.Revision).Code);var root=s.DiagnosticSnapshot().NewMilitary!.UnitDirective!.Dispatches.Last();At(s,root.DueAt);var r=s.DiagnosticSnapshot().NewMilitary!.UnitDirective!.Receipts.Last();Assert.False(r.Delivered);if(learn)At(s,r.ReplyDueAt);return root;}
 static void HomeUnits(WorldSession s){long end=s.DiagnosticSnapshot().NewMilitary!.Orders.Last().Routes.SelectMany(r=>r).Select(l=>l.EndAt).DefaultIfEmpty(s.Seconds).Max();At(s,Math.Max(s.Seconds,end+2));}
 static NewMilitaryInput Retry(WorldSession s,TroopDispatch root)=>Input(s,NewMilitaryAction.RetryUnitDirective) with{DirectiveRetry=new(NewGameMilitary.UnitDirectiveRetryContract,root.Id,NewGameMilitary.SelectKnownTarget(s.DiagnosticSnapshot(),root.Recipient)!),TransportPolicy=NewGameMilitary.UnitSenderEvidenceContract};

 static UnitHeldTransfer Handoff(WorldSession s,TroopDispatch root){var paper=NewGameMilitary.SelectDirectivePaper(s.DiagnosticSnapshot(),root.Id);Assert.NotNull(paper);var input=Input(s,NewMilitaryAction.DeliverHeldUnitDirective) with{DirectiveHandoff=paper};var result=s.DecideNewMilitary(input,s.PlayerControl,s.Revision);Assert.True(result.Code==ResultCode.Accepted,result.VisibleReason);return s.DiagnosticSnapshot().NewMilitary!.HeldDelivery!.Transfers.Last();}
 static TroopDispatch Cancel(WorldSession s,TroopDispatch root,long? effective=null){var w=s.DiagnosticSnapshot();var p=new UnitDirectiveCancellationInput(NewGameMilitary.UnitDirectiveCancellationContract,root.Id,NewGameMilitary.SelectKnownTarget(w,root.Recipient)!,effective??s.Seconds);var i=Input(s,NewMilitaryAction.CancelUnitDirective) with{DirectiveCancellation=p,DeliverBy=s.Seconds+600,PostPolicy=NewGameMilitary.UnitReplyRecoveryContract,TransportPolicy=NewGameMilitary.UnitSenderEvidenceContract};var result=s.DecideNewMilitary(i,s.PlayerControl,s.Revision);Assert.True(result.Code==ResultCode.Accepted,result.VisibleReason);return s.DiagnosticSnapshot().NewMilitary!.UnitDirective!.Cancellation!.Dispatches.Last();}
 [Theory][InlineData(0)][InlineData(1)][InlineData(2)]public void CancellationSuppressesOnlyOriginalBeforePhysicalLateArrival(int index){var s=Away();var root=FailedOriginal(s,true,index);HomeUnits(s);var cancel=Cancel(s,root);Assert.Empty(s.DiagnosticSnapshot().NewMilitary!.UnitDirective!.Cancellation!.Effects);At(s,cancel.DueAt-1);var restored=new WorldSession(s.DiagnosticSnapshot());foreach(var v in new[]{s,restored})At(v,cancel.DueAt);var w=s.DiagnosticSnapshot();Assert.Equal(UnitCancelDisposition.Suppressed,w.NewMilitary!.UnitDirective!.Cancellation!.Effects.Single().Outcome);Assert.False(MessageFlow.Knows(w.Messaging,w.NewMilitary.UnitDirective.Cancellation.Receipts.Single().ReplyMessage,w.PlayerControl.Value));var t=Handoff(s,root);At(s,t.DueAt);w=s.DiagnosticSnapshot();Assert.Equal(UnitDirectiveOutcome.Cancelled,w.NewMilitary!.UnitDirective!.Holding!.Outcomes.Single().Outcome);Assert.DoesNotContain(w.NewMilitary.Orders,o=>o.Action==NewMilitaryAction.SendUnitDirective);new WorldSession(w);}
 [Fact]public void FutureCancellationWaitsUntilRequestedTimeAndSurvivesRestore(){var s=Away();var root=FailedOriginal(s,true,1,UnitDirectiveKind.Hold);HomeUnits(s);long requested=s.Seconds+180;var cancel=Cancel(s,root,requested);At(s,cancel.DueAt);Assert.Empty(s.DiagnosticSnapshot().NewMilitary!.UnitDirective!.Cancellation!.Effects);At(s,requested-1);var restored=new WorldSession(s.DiagnosticSnapshot());foreach(var v in new[]{s,restored})At(v,requested);Assert.Equal(ContractJson.CanonicalHash(s.DiagnosticSnapshot()),ContractJson.CanonicalHash(restored.DiagnosticSnapshot()));var w=s.DiagnosticSnapshot();Assert.Equal(requested,w.NewMilitary!.UnitDirective!.Cancellation!.Effects.Single().At);Assert.Single(w.NewMilitary.UnitDirective.Cancellation.Notices);Assert.Equal(UnitCancelDisposition.Suppressed,w.NewMilitary.UnitDirective.Cancellation.Effects.Single().Outcome);new WorldSession(w);}
 [Fact]public void CompletedHoldCannotBeUndoneByCancellation(){var s=Away();var i=Directive(s,1,UnitDirectiveKind.Hold);Assert.Equal(ResultCode.Accepted,s.DecideNewMilitary(i,s.PlayerControl,s.Revision).Code);var root=s.DiagnosticSnapshot().NewMilitary!.UnitDirective!.Dispatches.Last();At(s,root.DueAt);var before=ContractJson.CanonicalHash(s.DiagnosticSnapshot().NewMilitary!.Orders);var cancel=Cancel(s,root);At(s,cancel.DueAt);var w=s.DiagnosticSnapshot();Assert.Equal(UnitCancelDisposition.TooLate,w.NewMilitary!.UnitDirective!.Cancellation!.Effects.Single().Outcome);Assert.Equal(before,ContractJson.CanonicalHash(w.NewMilitary.Orders));new WorldSession(w);}
 [Theory][InlineData(0)][InlineData(1)][InlineData(2)]public void FutureEffectStopsOnlyTheMovingOriginalAndKeepsOtherRoutes(int index){var s=Away();var i=Directive(s,index,UnitDirectiveKind.Move);Assert.Equal(ResultCode.Accepted,s.DecideNewMilitary(i,s.PlayerControl,s.Revision).Code);var root=s.DiagnosticSnapshot().NewMilitary!.UnitDirective!.Dispatches.Last();var cancel=Cancel(s,root,root.DueAt+2);Assert.Equal(root.DueAt,cancel.DueAt);At(s,root.DueAt+1);var before=s.DiagnosticSnapshot();Assert.True(before.NewMilitary!.UnitDirective!.Effects.Single().Outcome==UnitDirectiveOutcome.Applied);var restored=new WorldSession(before);foreach(var v in new[]{s,restored})At(v,root.DueAt+2);var w=s.DiagnosticSnapshot();var e=w.NewMilitary!.UnitDirective!.Cancellation!.Effects.Single();Assert.Equal(UnitCancelDisposition.Stopped,e.Outcome);Assert.Equal(new[]{index},w.NewMilitary.Orders.Single(o=>o.Id==e.StopOrder).AffectedUnits);foreach(var other in Enumerable.Range(0,3).Where(n=>n!=index))Assert.Equal(NewGameMilitary.Position(before,other,s.Seconds+20),NewGameMilitary.Position(w,other,s.Seconds+20));Assert.Equal(e.Position,NewGameMilitary.Position(w,index,s.Seconds+20));Assert.Equal(ContractJson.CanonicalHash(w),ContractJson.CanonicalHash(restored.DiagnosticSnapshot()));new WorldSession(w);}
 [Theory][InlineData(0)][InlineData(1)][InlineData(2)]public void SameTickCancellationSuppressesBothCopyAndHeldOriginal(int index){var s=Away();var root=FailedOriginal(s,true,index,UnitDirectiveKind.Hold);HomeUnits(s);var cancel=Cancel(s,root);Assert.Equal(ResultCode.Accepted,s.DecideNewMilitary(Retry(s,root),s.PlayerControl,s.Revision).Code);var copy=s.DiagnosticSnapshot().NewMilitary!.UnitDirective!.Dispatches.Last();var t=Handoff(s,root);Assert.Equal(cancel.DueAt,copy.DueAt);Assert.Equal(cancel.DueAt,t.DueAt);At(s,cancel.DueAt-1);var restored=new WorldSession(s.DiagnosticSnapshot());foreach(var v in new[]{s,restored})At(v,cancel.DueAt);var w=s.DiagnosticSnapshot();Assert.Equal(UnitCancelDisposition.Suppressed,w.NewMilitary!.UnitDirective!.Cancellation!.Effects.Single().Outcome);Assert.Equal(UnitDirectiveOutcome.Cancelled,w.NewMilitary.UnitDirective.Effects.Single().Outcome);Assert.Equal(UnitDirectiveOutcome.Cancelled,w.NewMilitary.UnitDirective.Holding!.Outcomes.Single().Outcome);Assert.DoesNotContain(w.NewMilitary.Orders,o=>o.Action==NewMilitaryAction.SendUnitDirective);Assert.Equal(ContractJson.CanonicalHash(w),ContractJson.CanonicalHash(restored.DiagnosticSnapshot()));new WorldSession(w);}
 [Fact]public void NewerHoldIsNotRolledBackByFutureCancellation(){var s=Away();var i=Directive(s,1,UnitDirectiveKind.Move);Assert.Equal(ResultCode.Accepted,s.DecideNewMilitary(i,s.PlayerControl,s.Revision).Code);var root=s.DiagnosticSnapshot().NewMilitary!.UnitDirective!.Dispatches.Last();var cancel=Cancel(s,root,root.DueAt+20);var hold=Directive(s,1,UnitDirectiveKind.Hold);Assert.Equal(ResultCode.Accepted,s.DecideNewMilitary(hold,s.PlayerControl,s.Revision).Code);At(s,root.DueAt);var before=ContractJson.CanonicalHash(s.DiagnosticSnapshot().NewMilitary!.Orders);At(s,root.DueAt+20);var w=s.DiagnosticSnapshot();Assert.Equal(UnitCancelDisposition.Superseded,w.NewMilitary!.UnitDirective!.Cancellation!.Effects.Single().Outcome);Assert.Equal(before,ContractJson.CanonicalHash(w.NewMilitary.Orders));new WorldSession(w);}
 [Fact]public void SavedCancellationEffectTamperingIsRejected(){var s=Away();var root=FailedOriginal(s,true,1,UnitDirectiveKind.Hold);HomeUnits(s);var cancel=Cancel(s,root);At(s,cancel.DueAt);var w=s.DiagnosticSnapshot();w.NewMilitary!.UnitDirective!.Cancellation!.Effects[0]=w.NewMilitary.UnitDirective.Cancellation.Effects[0] with{Outcome=UnitCancelDisposition.TooLate};Assert.Throws<InvalidDataException>(()=>new WorldSession(w));}
}
